+/// Shifts right by `shift` bits, where `1 <= shift <= 63`.
+#[inline(always)]
+fn shr_limbs(a: [u64; 4], shift: u32) -> [u64; 4] {
+    shr_limbs_with_carry(a, 0, shift)
+}
+
+#[inline(always)]
+fn shr_limbs_with_carry(a: [u64; 4], carry: u64, shift: u32) -> [u64; 4] {
+    let back = 64 - shift;
+    [
+        (a[0] >> shift) | (a[1] << back),
+        (a[1] >> shift) | (a[2] << back),
+        (a[2] >> shift) | (a[3] << back),
+        (a[3] >> shift) | (carry << back),
+    ]
+}
+
+/// Computes `a / 2^shift mod p` for canonical `a` and `1 <= shift <= 63`.
+///
+/// Since `p = -1 mod 2^64`, adding `m * p` with `m = a mod 2^shift` makes the
+/// sum divisible by `2^shift`, and the quotient stays below `p`.
+#[inline(always)]
+fn div_pow2_mod(a: [u64; 4], shift: u32) -> [u64; 4] {
+    let m = a[0] & ((1u64 << shift) - 1);
+    let (w0, carry) = mac(a[0], m, MODULUS[0], 0);
+    let (w1, carry) = mac(a[1], m, MODULUS[1], carry);
+    let (w2, carry) = mac(a[2], m, MODULUS[2], carry);
+    let (w3, w4) = mac(a[3], m, MODULUS[3], carry);
+
+    shr_limbs_with_carry([w0, w1, w2, w3], w4, shift)
+}

