+/// Computes `a^(p - 2)` in Montgomery form with a fixed addition chain.
+///
+/// `p - 2 = ffffffff 00000001 00000000 00000000 00000000 ffffffff ffffffff fffffffd`.
+fn invert_montgomery(a: [u64; 4]) -> [u64; 4] {
+    // x_k = a^(2^k - 1)
+    let x2 = montgomery_mul(montgomery_square(a), a);
+    let x3 = montgomery_mul(montgomery_square(x2), a);
+    let x6 = montgomery_mul(square_n(x3, 3), x3);
+    let x12 = montgomery_mul(square_n(x6, 6), x6);
+    let x15 = montgomery_mul(square_n(x12, 3), x3);
+    let x30 = montgomery_mul(square_n(x15, 15), x15);
+    let x32 = montgomery_mul(square_n(x30, 2), x2);
+
+    let t = montgomery_mul(square_n(x32, 32), a);
+    let t = montgomery_mul(square_n(t, 128), x32);
+    let t = montgomery_mul(square_n(t, 32), x32);
+    let t = montgomery_mul(square_n(t, 30), x30);
+    montgomery_mul(square_n(t, 2), a)
+}
